if(!exists('selection_bias_sensitivity',mode='function'))library(creditratingsystem)
fixture<-function(){
 target<-list(event='default',horizon=1,time_unit='months',probability_measure='PHYSICAL',conditioning='application');d<-list(model_id='comparison',model_version='1',parameter_version='1',data_fingerprint='applications',population_id='through-door',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2024-02-02',target=target)
 rows<-lapply(0:3,function(i)list(prediction_id=as.character(i),application_id=as.character(i),entity_id=as.character(i),cluster_id=as.character(i),segment='retail',as_of='2024-01-01',forecast_known_at='2024-01-01',horizon_end='2024-02-01',known_at='2024-02-02',complete_through='2024-02-01',model_id='comparison',model_version='1',parameter_version='1',funded=i<2,label_origin=if(i<2)'OBSERVED_OWN_CONTRACT'else'PSEUDO',outcome=if(i<2)i else 1,target=target,weight=1));candidates<-lapply(c('a','b'),function(m)list(model_id=m,model_hash=paste0('frozen-',m),training_entities=list(),training_known_at='2023-12-01',predictions=lapply(0:3,function(i)list(application_id=as.character(i),pd=if(m=='a')c(.2,.8,.6,.6)[i+1]else c(.4,.6,.6,.6)[i+1],known_at='2024-01-01'))));scenarios<-list()
 for(kind in c('IPW','BOUNDS','MNAR_SHIFT')){inputs<-list(observed=c(1,1,0,0),target_weights=rep(1,4));if(kind=='IPW'){inputs$propensities<-rep(.5,4);fn<-selection_ipw_weights}else{inputs$outcomes<-list(0,1,NULL,NULL);fn<-reject_inference_bounds};if(kind=='MNAR_SHIFT'){inputs$baseline_pd<-c(.2,.8,.6,.6);inputs$log_odds_shifts<-0;fn<-reject_inference_sensitivity};scenarios[[length(scenarios)+1]]<-list(result_id=kind,kind=kind,model_id='a',population_id='through-door',target=target,application_ids=as.list(as.character(0:3)),inputs=inputs,result=do.call(fn,inputs)$value)}
 list(candidates=candidates,evaluation_rows=rows,selection_results=scenarios,design=d,reference_model_id='a')
}
kw<-fixture();r<-do.call(selection_bias_sensitivity,kw)$value;m<-r$metrics;stopifnot(m$funded_count==2,m$mature_factual_count==2,abs(m$evidence_scopes$FUNDED_OBSERVED_TEST$a$brier-.04)<1e-12,abs(m$paired_candidate_minus_reference[['FUNDED_OBSERVED_TEST|b|brier']]-.12)<1e-12);s<-r$diagnostics$transport_scenarios;stopifnot(s[[1]]$recomputed_result$effective_sample_size==2,s[[2]]$recomputed_result$lower==.25,s[[2]]$recomputed_result$upper==.75,s[[3]]$recomputed_result$surface[[1]]$population_pd==.55,all(vapply(s,function(x)x$verified,logical(1))))
kw<-fixture();kw$selection_results[[1]]$inputs$propensities<-c(.5,.5,0,0);kw$selection_results[[1]]['result']<-list(NULL);r<-do.call(selection_bias_sensitivity,kw)$value;stopifnot(r$diagnostics$transport_scenarios[[1]]$status=='NOT_IDENTIFIED_ZERO_SUPPORT');kw$selection_results[[1]]$inputs$trim<-c(.1,1);kw$selection_results[[1]]$result<-do.call(selection_ipw_weights,kw$selection_results[[1]]$inputs)$value;r<-do.call(selection_bias_sensitivity,kw)$value;stopifnot(r$diagnostics$transport_scenarios[[1]]$recomputed_result$excluded_target_mass==2);kw$selection_results[[1]]$result$effective_sample_size<-3;stopifnot(do.call(selection_bias_sensitivity,kw)$value$decision$status=='BLOCKED')
kw<-fixture();kw$selection_results<-list();kw$evaluation_rows[[3]]$label_origin<-'SYNTHETIC_TRUTH';kw$evaluation_rows[[3]]$data_origin<-'SYNTHETIC';kw$evaluation_rows[[1]]$complete_through<-'2024-01-20';r<-do.call(selection_bias_sensitivity,kw)$value;stopifnot(r$metrics$evidence_scopes$SYNTHETIC_ENGINEERING_ONLY$a$n==1,r$metrics$mature_factual_count==1)
kw<-fixture();kw$uncertainty<-'cluster_bootstrap';kw$cluster_resamples<-list(list('0','1','0','1'),list('0','1','2','3'));r<-do.call(selection_bias_sensitivity,kw)$value;stopifnot(abs(r$uncertainty$intervals[['FUNDED_OBSERVED_TEST|b|brier']]$lower-.12)<1e-12);kw$selection_results[[2]]$inputs$outcomes[[3]]<-1;stopifnot(inherits(try(do.call(selection_bias_sensitivity,kw),silent=TRUE),'try-error'))
cat('Native selection validation PASS\n')
kw<-fixture();kw$evaluation_rows<-kw$evaluation_rows[1:3];r<-kw$evaluation_rows[[1]];r$as_of<-'2022-01-01';r$forecast_known_at<-'2022-01-01';r$horizon_end<-'2022-02-01';r$known_at<-'2022-02-02';r$weight<-0;r$label_origin<-'PSEUDO';r$funded<-FALSE;kw$evaluation_rows[[1]]<-r;kw$evaluation_rows[[2]]$outcome<-0;kw$evaluation_rows[[3]]$outcome<-1;kw$evaluation_rows[[3]]$label_origin<-'OBSERVED_OWN_CONTRACT';kw$evaluation_rows[[3]]$funded<-TRUE
for(i in seq_along(kw$candidates)){kw$candidates[[i]]$predictions<-kw$candidates[[i]]$predictions[1:3];kw$candidates[[i]]$training_known_at<-'2021-12-01';kw$candidates[[i]]$predictions[[1]]$known_at<-'2022-01-01'}
inputs<-list(observed=c(0,1,1),outcomes=list(NULL,0,1),target_weights=c(0,1,1),outcome_predictions=rep(.2,3),propensities=rep(.5,3),fold_lineage=list(nuisance_prediction_origin='OUT_OF_FOLD',folds=list(list(train=0,validation=c(1,2))),rows=lapply(kw$evaluation_rows,function(r)list(entity_id=r$entity_id,as_of=r$as_of,label_known_at=r$known_at,features_known_at=r$as_of))))
kw$selection_results<-list(list(result_id='aipw',kind='AIPW',model_id='a',population_id='through-door',target=kw$design$target,application_ids=as.list(as.character(0:2)),inputs=inputs,result=do.call(estimate_population_risk_aipw,inputs)$value));r<-do.call(selection_bias_sensitivity,kw)$value;s<-r$diagnostics$transport_scenarios[[1]];stopifnot(s$verified,abs(s$recomputed_result$population_pd-.8)<1e-12,abs(s$recomputed_result$standard_error-1)<1e-12)
